<script lang="ts">
 import {onMount} from 'svelte';import {atlasEvents,type AtlasEvent} from '../lib/atlas-events.js';
 let events:AtlasEvent[]=[];let filter='';
 $: visible=events.filter(event=>`${event.title} ${event.type} ${event.state}`.toLowerCase().includes(filter.toLowerCase()));
 onMount(()=>atlasEvents.subscribe(value=>events=value));
</script>
<section class="observability" aria-label="Observability"><header><div><strong>Observability</strong><small>Local operation history</small></div><input bind:value={filter} placeholder="Filter events" aria-label="Filter operation history"/><button onclick={()=>atlasEvents.clearUnpinned()}>Clear unpinned</button></header><div class="events">{#each visible.slice().reverse() as event (event.id)}<article class={`event ${event.state}`}><button title={event.pinned?'Unpin event':'Pin event'} onclick={()=>atlasEvents.pin(event.id,!event.pinned)}>{event.pinned?'★':'☆'}</button><div><b>{event.title}</b><small>{event.type} · {event.state}{event.message?` · ${event.message}`:''}</small></div></article>{/each}{#if !visible.length}<p>No operation events yet.</p>{/if}</div></section>
<style>.observability{height:100%;display:grid;grid-template-rows:auto 1fr;font-size:11px}.observability header{display:flex;gap:8px;align-items:center;padding:8px;border-bottom:1px solid var(--atlas-border)}.observability header div{margin-right:auto}.observability small{display:block;color:var(--atlas-muted)}.events{overflow:auto;padding:6px}.event{display:flex;gap:7px;padding:7px;border-bottom:1px solid color-mix(in srgb,var(--atlas-border) 55%,transparent)}.event.error{border-left:2px solid var(--atlas-danger)}.event.warning{border-left:2px solid var(--atlas-warning)}.event button{background:transparent;border:0;padding:0 2px}.event b{display:block}.events p{color:var(--atlas-muted)}</style>
